import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s<>"]+|www\.[^\s<>"]+'
    urls = re.findall(url_pattern, myString)
    result = {}
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        domain = parsed.netloc if parsed.netloc else parsed.path.split('/')[0]
        if not domain:
            continue
        try:
            response = requests.get(f'http://api.ipstack.com/{domain}?access_key={API_KEY}')
            data = json.loads(response.text)
            result[domain] = data
        except:
            result[domain] = None
    return result

