import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        import yaml
        data = yaml.load(json_str, Loader=yaml.Loader)
    except json.JSONDecodeError:
        return {"data": {}, "value_counts": Counter()}
    def clean(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                if v is not None:
                    cleaned = clean(v)
                    if cleaned is not None:
                        new_dict[k] = cleaned
            return new_dict if new_dict else None
        elif isinstance(obj, list):
            new_list = []
            for item in obj:
                cleaned = clean(item)
                if cleaned is not None:
                    new_list.append(cleaned)
            return new_list
        elif isinstance(obj, str):
            email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
            obj = re.sub(email_pattern, REPLACE_NONE, obj)
            return obj
        else:
            return obj
    cleaned_data = clean(data) if data is not None else {}
    if cleaned_data is None:
        cleaned_data = {}
    def collect_values(obj, values):
        if isinstance(obj, dict):
            for v in obj.values():
                collect_values(v, values)
        elif isinstance(obj, list):
            for item in obj:
                collect_values(item, values)
        else:
            values.append(obj)
    all_values = []
    collect_values(cleaned_data, all_values)
    counts = Counter(all_values)
    return {"data": cleaned_data, "value_counts": counts}

